const pages = [];
for (let i = 0; i <= 100; i++) {
  pages.push({ json: { page: i } });
}
return pages;

const clientes = [];

const limparData = (d) => {
  if (!d || d === '0000-00-00') return null;
  return d;
};

const normalizar = (c) => ({
  json: {
    belle_id:      parseInt(c.codigo),
    nome:          (c.nome || '').replace(/'/g, "''"),
    telefone:      c.telefone || '',
    celular:       (c.celular || '').replace(/[^0-9+]/g, ''),
    celular2:      (c.celular2 || '').replace(/[^0-9+]/g, ''),
    cpf:           c.cpf || '',
    email:         c.email || '',
    dt_nascimento: limparData(c.dtNascimento),
    dt_cadastro:   limparData(c.dtCadastro),
    sexo:          c.sexo || '',
    profissao:     (c.profissao || '').replace(/'/g, "''"),
    temperatura:   c.temperatura || '',
    rating:        c.rating !== undefined ? c.rating : null,
    pontos:        parseInt(c.pontos) || 0,
    uf:            c.UF || '',
    cidade:        (c.cidade || '').replace(/'/g, "''"),
    bairro:        (c.bairro || '').replace(/'/g, "''"),
    cep:           c.cep || '',
    endereco:      (c.endereco || '').replace(/'/g, "''"),
    num_endereco:  c.numEndereco || '',
    tipo_origem:   c.tipoOrigem || '',
    origem:        (c.origem || '').replace(/'/g, "''"),
    tags:          JSON.stringify(c.tags || [])
  }
});

for (const item of $input.all()) {
  const data = item.json;
  if (Array.isArray(data)) {
    for (const c of data) {
      if (c.codigo) clientes.push(normalizar(c));
    }
  } else if (data && data.codigo) {
    clientes.push(normalizar(data));
  }
}

console.log(`Total de clientes: ${clientes.length}`);
return clientes;
